def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty)
    sell_book = []  # list of (price, arrival_time, id, qty)
    order_book = {}  # id -> (side, price, arrival_time, remaining_qty)
    arrival_counter = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_book:
                side, price, arr_time, remaining_qty = order_book[order_id]
                del order_book[order_id]
                # Remove from book
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            remaining_qty = qty

            if side == 'buy':
                # Match against sell book (lowest price first, then earliest arrival)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arr_time, sell_id, sell_qty = sell_book[i]
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_book[i] = (sell_price, sell_arr_time, sell_id, sell_qty - trade_qty)
                        if sell_book[i][3] == 0:
                            del order_book[sell_id]
                            sell_book.pop(i)
                        else:
                            i += 1
                    else:
                        break
            else:  # side == 'sell'
                # Match against buy book (highest price first, then earliest arrival)
                buy_book.sort(key=lambda x: (-x[0], x[1]))
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    buy_price, buy_arr_time, buy_id, buy_qty = buy_book[i]
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_book[i] = (buy_price, buy_arr_time, buy_id, buy_qty - trade_qty)
                        if buy_book[i][3] == 0:
                            del order_book[buy_id]
                            buy_book.pop(i)
                        else:
                            i += 1
                    else:
                        break

            # Add remaining to book if limit order
            if remaining_qty > 0 and order_type == 'limit':
                order_book[order_id] = (side, price, arrival_counter, remaining_qty)
                if side == 'buy':
                    buy_book.append((price, arrival_counter, order_id, remaining_qty))
                else:
                    sell_book.append((price, arrival_counter, order_id, remaining_qty))

            arrival_counter += 1

    return trades

